/// <summary>
/// PricingAttribute of table <c>InventTable</c> field Width.
/// </summary>
[UPSPricingMetadataDiscovery][UPSPricingAttributeSourceDiscovery(UPSPricingAttributeSource::Product, UPSPricingAttributeSourceLevel::Line)]
internal class UPSPricingAttributeInventTableWidth extends UPSPricingAttributeInventTable implements UPSIPricingAttribute
{
}

Method.Source:
public str getName()
{
    return fieldPName(InventTable, Width);
}

public Set getAllowedValues()
{
    var         ret = new Set(Types::Real);
    InventTable inventTable;

    while select inventTable
        group by Width
    {
        if (! ret.in(inventTable.Width))
        {
            ret.add(inventTable.Width);
        }
    }

    return ret;
}

protected void setQueryBuildDatasourceRange(QueryBuildDataSource _qbds, anytype _value)
{
    QueryBuildRange qbr;

    qbr = _qbds.addRange(fieldNum(InventTable, Width));
    qbr.value(queryValue(_value));
}
